// Memory bandwidth index — record JAH-GPC-RAM-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"capacity_gb": 16, "speed_mts": 5600, "latency_cl": 46};
var value = (m.capacity_gb*m.speed_mts/m.latency_cl/100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-RAM-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-RAM-000001|' + value.toFixed(2) + ' bandwidth index');

